    #[test]
    fn concurrent_writes_to_same_entry_never_corrupt() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = root.clone();
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    let content = format!("content-from-thread-{}", i);
                    store
                        .store("http:test", "shared-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        // After all threads finish, the entry must be consistent:
        // content and metadata must come from the same write.
        let store = CacheStore::new(&root);
        let entry = store.load("http:test", "shared-template").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();

        assert!(
            content.starts_with("content-from-thread-"),
            "content should be from one of the threads, got: {}",
            content
        );
        assert_eq!(entry.metadata.size_bytes, content.len() as u64);
    }

    #[test]
    fn concurrent_writes_to_different_entries() {
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = root.clone();
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    let name = format!("template-{}", i);
                    let content = format!("content-{}", i);
                    store.store("http:test", &name, &content, 3600).unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let store = CacheStore::new(&root);
        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 8);

        // Verify each entry has the correct content
        for i in 0..8 {
            let name = format!("template-{}", i);
            let entry = store.load("http:test", &name).unwrap().unwrap();
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, format!("content-{}", i));
        }
    }

    #[test]
    fn concurrent_store_and_load_no_errors() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();

        // Seed an initial entry
        let store = CacheStore::new(&root);
        store
            .store("http:test", "contested", "initial", 3600)
            .unwrap();

        let barrier = Arc::new(Barrier::new(8));

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = root.clone();
                let barrier = Arc::clone(&barrier);
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    barrier.wait();

                    if i % 2 == 0 {
                        // Writers
                        let content = format!("update-{}", i);
                        store
                            .store("http:test", "contested", &content, 3600)
                            .unwrap();
                    } else {
                        // Readers
                        for _ in 0..10 {
                            let result = store.load("http:test", "contested").unwrap();
                            // Must never get a corrupted/partial read
                            if let Some(entry) = result {
                                let content = store.read_content(&entry).unwrap();
                                assert!(
                                    content == "initial" || content.starts_with("update-"),
                                    "unexpected content: {}",
                                    content
                                );
                            }
                        }
                    }
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }
    }
